<?php
class CC_DB { public static function table(){global $wpdb;return $wpdb->prefix.'cc_ratings';} public static function logs(){global $wpdb;return $wpdb->prefix.'cc_review_logs';} public static function init(){add_action('init',array('CC_Plugin','register_submission'));} public static function install(){global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$c=$wpdb->get_charset_collate();dbDelta('CREATE TABLE '.self::table().' (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,city_id bigint(20) unsigned NOT NULL,user_id bigint(20) unsigned NOT NULL DEFAULT 0,voter_key varchar(64) NOT NULL DEFAULT \'\',stars tinyint unsigned NOT NULL,created_at datetime NOT NULL,updated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY voter_city(voter_key,city_id),KEY city_id(city_id),KEY user_id(user_id)) '.$c.';');self::migrate_legacy();dbDelta('CREATE TABLE '. $wpdb->prefix.'cc_badges_users (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,user_id bigint(20) unsigned NOT NULL,badge_key varchar(80) NOT NULL,awarded_at datetime NOT NULL,PRIMARY KEY(id),UNIQUE KEY user_badge(user_id,badge_key)) '.$c.';');dbDelta('CREATE TABLE '. $wpdb->prefix.'cc_points_log (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,user_id bigint(20) unsigned NOT NULL,points int NOT NULL,reason varchar(100) NOT NULL,submission_id bigint(20) unsigned DEFAULT 0,created_at datetime NOT NULL,PRIMARY KEY(id),KEY user_id(user_id),KEY submission_id(submission_id)) '.$c.';');dbDelta('CREATE TABLE '.self::logs().' (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,submission_id bigint(20) unsigned NOT NULL,reviewer_id bigint(20) unsigned NOT NULL,from_status varchar(20) NOT NULL,to_status varchar(20) NOT NULL,note text,created_at datetime NOT NULL,PRIMARY KEY(id),KEY submission_id(submission_id),KEY reviewer_id(reviewer_id)) '.$c.';');}
 public static function migrate_legacy(){global $wpdb;$t=self::table();if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$t))!==$t)return;$cols=$wpdb->get_col("SHOW COLUMNS FROM $t",0);if(!in_array('voter_key',$cols,true)){$wpdb->query("ALTER TABLE $t ADD COLUMN voter_key varchar(64) NOT NULL DEFAULT '' AFTER user_id");}$cols2=$wpdb->get_col("SHOW COLUMNS FROM $t",0);if(!in_array('updated_at',$cols2,true)){$wpdb->query("ALTER TABLE $t ADD COLUMN updated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP AFTER created_at");}$wpdb->query("UPDATE $t SET voter_key=CONCAT('u',user_id) WHERE voter_key=''");$idx=$wpdb->get_results("SHOW INDEX FROM $t");$names=array();foreach((array)$idx as $r)$names[$r->Key_name]=1;if(isset($names['user_city']))$wpdb->query("ALTER TABLE $t DROP INDEX user_city");if(!isset($names['voter_city']))$wpdb->query("ALTER TABLE $t ADD UNIQUE KEY voter_city(voter_key,city_id)");}
 public static function recalc($city){global $wpdb;$t=self::table();$row=$wpdb->get_row($wpdb->prepare("SELECT COALESCE(SUM(stars),0) s,COUNT(*) c FROM $t WHERE city_id=%d",$city));update_post_meta($city,'cc_rating_sum',(int)$row->s);update_post_meta($city,'cc_rating_count',(int)$row->c);update_post_meta($city,'cc_rating_avg',$row->c?round($row->s/$row->c,1):0);delete_site_transient('cc_ranking');/* پاک‌کردن کش لایت‌اسپید تا صفحهٔ اول و صفحهٔ شهر بی‌درنگ پس از هر رأی به‌روز شوند */do_action('litespeed_purge_all','sa-cc-vote');}
}
